// num_bigint_version: no inputs, returns an opaque integer version.
// We call it once and record the value in global attributes for consistency checks
// across subsequent invocations within the same process.
int v = num_bigint_version();

// If we've seen a version before in this process, assert it is stable.
int seen = FUZZ_GET_ATTR_INT_GLOBAL("nb_ver_has");
if (seen) {
    int prev = FUZZ_GET_ATTR_INT_GLOBAL("nb_ver");
    // Property: library version should be deterministic within a single process run.
    FUZZ_ASSERT(prev == v, "num_bigint_version changed across calls in the same process");
}

// Record the observed version for future calls.
FUZZ_SET_ATTR_INT_GLOBAL("nb_ver", v);
FUZZ_SET_ATTR_INT_GLOBAL("nb_ver_has", 1);

// No outputs to return; this function does not produce managed objects.
// Validation: The stub enforces zero-arg call and asserts version stability intra-process.
